mapper.select:
SELECT 
FROM ocean_gis.gis_tile_set_archive a
JOIN ocean_gis.gis_processing_task t ON t.id = a.processing_task_id
WHERE a.deleted = 0

    AND a.archive_no LIKE CONCAT('%', #{archiveNo}, '%')


    AND t.task_no LIKE CONCAT('%', #{taskNo}, '%')


    AND t.task_name LIKE CONCAT('%', #{taskName}, '%')


    AND t.processing_type = #{processingType}


    AND a.archive_status = #{archiveStatus}


    AND a.create_time >= #{createTimeStart}


    AND a.create_time <= #{createTimeEnd}

ORDER BY a.create_time DESC, a.id DESC
